"""Assets, stylesheets, and UI shell scaffolding for Dashboard V2 (Issue #53)."""

from __future__ import annotations

from pathlib import Path

from crash_trend.dashboard.navigation import (
    get_nav_menu_html,
    get_navigation_js,
    get_route_revalidate_call,
    get_routing_init_call,
)

DEFAULT_ROOT = Path(__file__).resolve().parent.parent.parent
VENDOR_JS = DEFAULT_ROOT / "vendor" / "chart.umd.min.js"


def get_vendor_chartjs(vendor_path: Path | str | None = None) -> str:
    """Reads vendor Chart.js library or returns an empty fallback if missing."""
    v_file = Path(vendor_path) if vendor_path else VENDOR_JS
    if v_file.is_file():
        return v_file.read_text(encoding="utf-8")
    return "/* Chart.js vendor script not found */"


def get_dashboard_styles() -> str:
    """Returns the complete CSS stylesheet for Dashboard V2."""
    return '<style>\n  :root {\n    --bg-app: #f8fafc;\n    --bg-surface: #ffffff;\n    --bg-subtle: #f1f5f9;\n    --bg-muted: #e2e8f0;\n    --border: #e2e8f0;\n    --border-subtle: #f1f5f9;\n    --border-hover: #cbd5e1;\n    --text-main: #0f172a;\n    --text-muted: #64748b;\n    --text-subtle: #94a3b8;\n    --accent: #2563eb;\n    --accent-light: #eff6ff;\n    --accent-hover: #1d4ed8;\n    --accent-text: #1d4ed8;\n    --success: #10b981;\n    --success-light: #ecfdf5;\n    --success-text: #047857;\n    --warning: #f59e0b;\n    --warning-light: #fffbeb;\n    --warning-text: #b45309;\n    --danger: #ef4444;\n    --danger-light: #fef2f2;\n    --danger-text: #b91c1c;\n    --p0: #dc2626;\n    --p0-bg: #fee2e2;\n    --p1: #d97706;\n    --p1-bg: #fef3c7;\n    --p2: #2563eb;\n    --p2-bg: #dbeafe;\n    --p3: #64748b;\n    --p3-bg: #f1f5f9;\n    --sidebar-w: 240px;\n    --sidebar-collapsed-w: 72px;\n    --header-h: 64px;\n    --radius-sm: 6px;\n    --radius-md: 8px;\n    --radius-lg: 12px;\n    --radius-full: 9999px;\n    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n    --shadow-card: 0 1px 3px 0 rgba(0, 0, 0, 0.08), 0 1px 2px -1px rgba(0, 0, 0, 0.05);\n    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);\n    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.03);\n    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, "Noto Sans TC", "PingFang TC", sans-serif;\n    --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;\n  }\n\n  [data-theme="dark"] {\n    --bg-app: #0b1120;\n    --bg-surface: #131d33;\n    --bg-subtle: #1e293b;\n    --bg-muted: #334155;\n    --border: #24324d;\n    --border-subtle: #1a263d;\n    --border-hover: #475569;\n    --text-main: #f8fafc;\n    --text-muted: #94a3b8;\n    --text-subtle: #64748b;\n    --accent: #3b82f6;\n    --accent-light: rgba(59, 130, 246, 0.15);\n    --accent-hover: #60a5fa;\n    --accent-text: #93c5fd;\n    --shadow-card: 0 1px 3px 0 rgba(0, 0, 0, 0.4);\n    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5);\n    --danger-light: rgba(239, 68, 68, 0.2);\n    --danger-text: #fca5a5;\n    --warning-light: rgba(245, 158, 11, 0.2);\n    --warning-text: #fcd34d;\n    --success-light: rgba(16, 185, 129, 0.2);\n    --success-text: #6ee7b7;\n    --p0-bg: rgba(220, 38, 38, 0.25);\n    --p1-bg: rgba(217, 119, 6, 0.25);\n    --p2-bg: rgba(37, 99, 235, 0.25);\n    --p3-bg: rgba(100, 116, 139, 0.25);\n  }\n\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  html { -webkit-font-smoothing: antialiased; }\n  body {\n    background: var(--bg-app);\n    color: var(--text-main);\n    font: 14px/1.5 var(--font-sans);\n    min-height: 100vh;\n    display: flex;\n    overflow-x: hidden;\n  }\n\n  /* ── Sidebar (左側導覽列) ────────────────────────── */\n  .sidebar {\n    width: var(--sidebar-w);\n    background: var(--bg-surface);\n    border-right: 1px solid var(--border);\n    display: flex;\n    flex-direction: column;\n    position: fixed;\n    top: 0;\n    left: 0;\n    bottom: 0;\n    z-index: 50;\n    transition: width 0.2s ease, transform 0.2s ease;\n  }\n  .sidebar.collapsed {\n    width: var(--sidebar-collapsed-w);\n  }\n  .sidebar-header {\n    height: var(--header-h);\n    display: flex;\n    align-items: center;\n    padding: 0 16px;\n    border-bottom: 1px solid var(--border);\n    gap: 10px;\n  }\n  .brand-logo {\n    width: 32px;\n    height: 32px;\n    border-radius: var(--radius-md);\n    background: linear-gradient(135deg, var(--accent), #4f46e5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #ffffff;\n    flex-shrink: 0;\n    box-shadow: 0 2px 4px rgba(37, 99, 235, 0.3);\n  }\n  .brand-info {\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n    white-space: nowrap;\n  }\n  .brand-title {\n    font-size: 15px;\n    font-weight: 700;\n    color: var(--text-main);\n    letter-spacing: -0.01em;\n  }\n  .brand-sub {\n    font-size: 11px;\n    font-weight: 500;\n    color: var(--text-muted);\n  }\n  .brand-badge {\n    display: inline-block;\n    font-size: 9px;\n    font-weight: 700;\n    padding: 1px 5px;\n    border-radius: 4px;\n    background: var(--accent-light);\n    color: var(--accent-text);\n    margin-left: 6px;\n  }\n  .sidebar.collapsed .brand-info { display: none; }\n\n  .nav-menu {\n    flex: 1;\n    padding: 14px 10px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    overflow-y: auto;\n  }\n  .nav-item {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 9px 12px;\n    border-radius: var(--radius-md);\n    color: var(--text-muted);\n    font-size: 13.5px;\n    font-weight: 500;\n    cursor: pointer;\n    text-decoration: none;\n    transition: background 0.15s, color 0.15s;\n    user-select: none;\n    border: none;\n    background: transparent;\n    width: 100%;\n    text-align: left;\n  }\n  .nav-item:hover {\n    background: var(--bg-subtle);\n    color: var(--text-main);\n  }\n  .nav-item.active {\n    background: var(--accent-light);\n    color: var(--accent-text);\n    font-weight: 600;\n  }\n  .nav-icon {\n    width: 20px;\n    height: 20px;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .sidebar.collapsed .nav-label { display: none; }\n\n  .sidebar-footer {\n    padding: 12px;\n    border-top: 1px solid var(--border);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 8px;\n  }\n  .collapse-btn {\n    padding: 6px 8px;\n    border-radius: var(--radius-sm);\n    border: 1px solid var(--border);\n    background: var(--bg-surface);\n    color: var(--text-muted);\n    cursor: pointer;\n    font-size: 12px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all 0.15s;\n  }\n  .collapse-btn:hover {\n    color: var(--text-main);\n    border-color: var(--border-hover);\n  }\n\n  /* ── Main Layout Wrapper ─────────────────────────── */\n  .layout-wrapper {\n    flex: 1;\n    margin-left: var(--sidebar-w);\n    display: flex;\n    flex-direction: column;\n    min-width: 0;\n    transition: margin-left 0.2s ease;\n  }\n  .sidebar.collapsed + .layout-wrapper {\n    margin-left: var(--sidebar-collapsed-w);\n  }\n\n  /* ── Header (頂部功能列) ─────────────────────────── */\n  header.top-header {\n    height: var(--header-h);\n    background: var(--bg-surface);\n    border-bottom: 1px solid var(--border);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0 24px;\n    position: sticky;\n    top: 0;\n    z-index: 40;\n  }\n  .header-left {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n  }\n  .mobile-toggle {\n    display: none;\n    border: 1px solid var(--border);\n    background: var(--bg-surface);\n    padding: 6px 8px;\n    border-radius: var(--radius-sm);\n    cursor: pointer;\n  }\n  .app-select-wrap {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .app-label {\n    font-size: 11px;\n    font-weight: 700;\n    color: var(--text-subtle);\n    letter-spacing: 0.05em;\n    text-transform: uppercase;\n  }\n  .app-selector {\n    font-size: 13.5px;\n    font-weight: 600;\n    color: var(--text-main);\n    background: var(--bg-subtle);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 6px 12px;\n    cursor: pointer;\n    outline: none;\n    transition: border-color 0.15s, box-shadow 0.15s;\n  }\n  .app-selector:focus {\n    border-color: var(--accent);\n    box-shadow: 0 0 0 2px var(--accent-light);\n  }\n\n  /* Date / Period Filter */\n  .period-filters {\n    display: inline-flex;\n    background: var(--bg-subtle);\n    padding: 3px;\n    border-radius: var(--radius-md);\n    border: 1px solid var(--border);\n  }\n  .period-btn {\n    border: none;\n    background: transparent;\n    padding: 4px 10px;\n    font-size: 12px;\n    font-weight: 500;\n    color: var(--text-muted);\n    border-radius: var(--radius-sm);\n    cursor: pointer;\n    transition: all 0.15s;\n  }\n  .period-btn.active {\n    background: var(--bg-surface);\n    color: var(--text-main);\n    font-weight: 600;\n    box-shadow: var(--shadow-sm);\n  }\n\n  .header-right {\n    display: flex;\n    align-items: center;\n    gap: 14px;\n  }\n  .search-box {\n    position: relative;\n    display: flex;\n    align-items: center;\n  }\n  .search-input {\n    width: 220px;\n    height: 34px;\n    padding: 0 12px 0 32px;\n    font-size: 13px;\n    border-radius: var(--radius-md);\n    border: 1px solid var(--border);\n    background: var(--bg-subtle);\n    color: var(--text-main);\n    outline: none;\n    transition: width 0.2s, border-color 0.15s;\n  }\n  .search-input:focus {\n    width: 280px;\n    border-color: var(--accent);\n    background: var(--bg-surface);\n  }\n  .search-icon {\n    position: absolute;\n    left: 10px;\n    width: 14px;\n    height: 14px;\n    color: var(--text-subtle);\n    pointer-events: none;\n  }\n\n  /* Sources Availability Chips in Header */\n  .source-badges {\n    display: flex;\n    gap: 6px;\n    align-items: center;\n  }\n  .src-chip {\n    font-size: 11px;\n    font-weight: 600;\n    padding: 3px 8px;\n    border-radius: var(--radius-full);\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    background: var(--bg-subtle);\n    color: var(--text-muted);\n    border: 1px solid var(--border);\n  }\n  .src-dot {\n    width: 6px;\n    height: 6px;\n    border-radius: 50%;\n  }\n  .src-dot.available { background: var(--success); box-shadow: 0 0 0 2px var(--success-light); }\n  .src-dot.unavailable { background: var(--text-subtle); }\n  .src-dot.disabled { background: var(--text-subtle); }\n  .src-dot.stale { background: var(--warning); box-shadow: 0 0 0 2px var(--warning-light); }\n  .src-dot.insufficient_data { background: var(--accent); box-shadow: 0 0 0 2px var(--accent-light); }\n  .src-dot.error { background: var(--danger); box-shadow: 0 0 0 2px var(--danger-light); }\n\n  .theme-toggle-btn {\n    width: 34px;\n    height: 34px;\n    border-radius: var(--radius-md);\n    border: 1px solid var(--border);\n    background: var(--bg-surface);\n    color: var(--text-muted);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: all 0.15s;\n  }\n  .theme-toggle-btn:hover {\n    color: var(--text-main);\n    border-color: var(--border-hover);\n  }\n\n  /* ── Content Area & Views ────────────────────────── */\n  main.content-area {\n    padding: 24px;\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    gap: 24px;\n  }\n  .view-container {\n    display: none;\n    flex-direction: column;\n    gap: 20px;\n    animation: fadeIn 0.18s ease-in-out;\n  }\n  .view-container.active {\n    display: flex;\n  }\n\n  /* \u2500\u2500 Workspace Tabs (工作區內 panel 切換, Issue #75) ── */\n  .ws-tabstrip {\n    display: none;\n    gap: 6px;\n    padding: 4px;\n    background: var(--bg-subtle);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    overflow-x: auto;\n  }\n  .ws-tabstrip.active {\n    display: flex;\n  }\n  .ws-tab {\n    flex-shrink: 0;\n    padding: 7px 14px;\n    border: none;\n    background: transparent;\n    border-radius: var(--radius-sm);\n    color: var(--text-muted);\n    font-size: 13px;\n    font-weight: 500;\n    cursor: pointer;\n    white-space: nowrap;\n    transition: background 0.15s, color 0.15s;\n  }\n  .ws-tab:hover {\n    color: var(--text-main);\n  }\n  .ws-tab.active {\n    background: var(--bg-surface);\n    color: var(--accent-text);\n    font-weight: 600;\n    box-shadow: var(--shadow-sm);\n  }\n  @keyframes fadeIn {\n    from { opacity: 0; transform: translateY(4px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  /* ── Section Titles ──────────────────────────────── */\n  .section-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 2px;\n  }\n  .section-title {\n    font-size: 17px;\n    font-weight: 700;\n    color: var(--text-main);\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .section-subtitle {\n    font-size: 13px;\n    color: var(--text-muted);\n    font-weight: 400;\n  }\n\n  /* ── KPI Cards (首頁指標卡) ──────────────────────── */\n  /* Release Decision 首屏（#73）。色調是正確性的一部分，不只是樣式：\n     decision-tone-neutral 覆蓋 insufficient_data / baseline / gate 未評估，\n     必須與 decision-tone-good 明顯不同，否則沒判定過的版本會被讀成綠燈。 */\n  .decision-section {\n    margin-bottom: 20px;\n  }\n  .decision-section-head {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 12px;\n    margin-bottom: 10px;\n    flex-wrap: wrap;\n  }\n  .decision-section-title {\n    font-size: 15px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .decision-section-subtitle {\n    font-size: 12px;\n    color: var(--text-muted);\n  }\n  .decision-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 16px;\n    align-items: start;\n  }\n  .decision-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-left: 4px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 14px 16px;\n    box-shadow: var(--shadow-card);\n  }\n  .decision-tone-good {\n    border-left-color: var(--success);\n    background: var(--success-light);\n  }\n  .decision-tone-warn {\n    border-left-color: var(--warning);\n    background: var(--warning-light);\n  }\n  .decision-tone-bad {\n    border-left-color: var(--danger);\n    background: var(--danger-light);\n  }\n  .decision-tone-neutral {\n    border-left-color: var(--border-hover);\n    background: var(--bg-subtle);\n  }\n  .decision-card-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n  }\n  .decision-platform {\n    font-size: 13px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .decision-gate-badge {\n    font-size: 11.5px;\n    font-weight: 700;\n    padding: 2px 8px;\n    border: 1px solid var(--border);\n    border-radius: var(--radius-full);\n    background: var(--bg-surface);\n    color: var(--text-main);\n    white-space: nowrap;\n  }\n  .decision-version {\n    margin-top: 6px;\n    font-family: var(--font-mono);\n    font-size: 18px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .decision-recommendation {\n    margin-top: 8px;\n    font-size: 13px;\n    line-height: 1.5;\n    color: var(--text-main);\n  }\n  .decision-action-row {\n    margin-top: 6px;\n    font-size: 12px;\n    color: var(--text-muted);\n  }\n  .decision-action {\n    font-family: var(--font-mono);\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .decision-unevaluated {\n    margin-top: 8px;\n    font-size: 12.5px;\n    line-height: 1.5;\n    color: var(--text-muted);\n  }\n  .decision-reasons-label {\n    margin-top: 10px;\n    font-size: 11.5px;\n    font-weight: 700;\n    color: var(--text-muted);\n  }\n  .decision-reasons {\n    margin: 4px 0 0;\n    padding-left: 18px;\n    font-size: 12.5px;\n    line-height: 1.55;\n    color: var(--text-main);\n  }\n  .decision-chip-row {\n    margin-top: 10px;\n    display: flex;\n    gap: 6px;\n    flex-wrap: wrap;\n  }\n  .decision-chip {\n    font-size: 11px;\n    padding: 2px 8px;\n    border-radius: var(--radius-full);\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    color: var(--text-main);\n  }\n  .decision-chip.is-neutral {\n    color: var(--text-muted);\n    background: var(--bg-muted);\n  }\n\n  /* ── Previous Release Comparison（#74 首屏 gate 對齊比較面）─────────\n     每個 metric 的 classification 色調由 Python 端的 COMPARISON_CLASS_PREFIX\n     注入 class 名，因此 CSS 與 JS 不可能各自漂移。comparison-class-neutral\n     覆蓋「沒有比較資料」，必須與 comparison-class-good 明顯不同。 */\n  .comparison-section {\n    margin-bottom: 20px;\n  }\n  .comparison-section-head {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 12px;\n    margin-bottom: 10px;\n    flex-wrap: wrap;\n  }\n  .comparison-section-title {\n    font-size: 15px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .comparison-section-subtitle {\n    font-size: 12px;\n    color: var(--text-muted);\n  }\n  .comparison-grid {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 16px;\n    align-items: start;\n  }\n  .comparison-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 14px 16px;\n    box-shadow: var(--shadow-card);\n  }\n  .comparison-card.is-neutral {\n    background: var(--bg-subtle);\n  }\n  .comparison-card-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n  }\n  .comparison-platform {\n    font-size: 13px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .comparison-window {\n    font-size: 11.5px;\n    color: var(--text-muted);\n    white-space: nowrap;\n  }\n  .comparison-version {\n    margin-top: 6px;\n    font-family: var(--font-mono);\n    font-size: 16px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .comparison-scope {\n    margin-top: 6px;\n    font-size: 11.5px;\n    line-height: 1.5;\n    color: var(--text-muted);\n  }\n  .comparison-scope.is-neutral {\n    padding: 6px 8px;\n    border: 1px dashed var(--border-hover);\n    border-radius: var(--radius-sm);\n    background: var(--bg-muted);\n  }\n  .comparison-unavailable {\n    margin-top: 8px;\n    font-size: 12.5px;\n    line-height: 1.5;\n    color: var(--text-muted);\n  }\n  .comparison-metrics {\n    margin-top: 10px;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n  }\n  .comparison-metric {\n    padding: 8px 10px;\n    border: 1px solid var(--border);\n    border-radius: var(--radius-sm);\n    background: var(--bg-app);\n  }\n  .comparison-metric-head {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    flex-wrap: wrap;\n  }\n  .comparison-metric-label {\n    font-size: 12.5px;\n    font-weight: 700;\n    color: var(--text-main);\n  }\n  .comparison-metric-change {\n    font-family: var(--font-mono);\n    font-size: 13px;\n    font-weight: 700;\n    color: var(--text-main);\n    margin-left: auto;\n  }\n  .comparison-metric-threshold {\n    margin-top: 4px;\n    font-size: 11px;\n    font-family: var(--font-mono);\n    color: var(--text-muted);\n    word-break: break-word;\n  }\n  .comparison-metric-reason {\n    margin-top: 3px;\n    font-size: 11.5px;\n    line-height: 1.5;\n    color: var(--text-secondary);\n  }\n  .comparison-class-good,\n  .comparison-class-warn,\n  .comparison-class-bad,\n  .comparison-class-neutral {\n    font-size: 11px;\n    font-weight: 700;\n    padding: 2px 8px;\n    border-radius: var(--radius-full);\n    white-space: nowrap;\n  }\n  .comparison-class-good { background: var(--success-light); color: var(--success-text); }\n  .comparison-class-warn { background: var(--warning-light); color: var(--warning-text); }\n  .comparison-class-bad { background: var(--danger-light); color: var(--danger-text); }\n  .comparison-class-neutral { background: var(--bg-muted); color: var(--text-muted); border: 1px solid var(--border); }\n  .comparison-chip {\n    font-size: 11px;\n    padding: 2px 8px;\n    border-radius: var(--radius-full);\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    color: var(--text-main);\n  }\n  .comparison-chip.is-requested {\n    background: var(--accent-light);\n    color: var(--accent-text);\n    border-color: var(--accent);\n  }\n\n  /* Top Issues 操作入口（#74）。 */\n  .top-issue-actions {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    align-items: flex-start;\n  }\n  .top-issue-action {\n    font-size: 11.5px;\n    font-weight: 600;\n    color: var(--accent-text);\n    text-decoration: none;\n    background: none;\n    border: none;\n    padding: 0;\n    cursor: pointer;\n    white-space: nowrap;\n  }\n  .top-issue-action:hover {\n    text-decoration: underline;\n  }\n  .top-issue-action-absent {\n    font-size: 11px;\n    color: var(--text-muted);\n    white-space: nowrap;\n  }\n  .decision-chip.is-requested {\n    color: var(--accent-text);\n    background: var(--accent-light);\n    border-color: var(--accent);\n    font-weight: 600;\n  }\n  .decision-permalink {\n    display: inline-block;\n    margin-top: 10px;\n    font-size: 11.5px;\n    color: var(--accent-text);\n    text-decoration: none;\n  }\n  .decision-permalink:hover {\n    text-decoration: underline;\n  }\n  @media (max-width: 900px) {\n    .decision-grid { grid-template-columns: 1fr; }\n  }\n\n  .kpi-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 16px;\n  }\n  @media (max-width: 1100px) {\n    .kpi-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 640px) {\n    .kpi-grid { grid-template-columns: 1fr; }\n  }\n\n  .kpi-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-lg);\n    padding: 20px;\n    box-shadow: var(--shadow-card);\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n    position: relative;\n    overflow: hidden;\n    transition: transform 0.15s, box-shadow 0.15s;\n  }\n  .kpi-card:hover {\n    box-shadow: var(--shadow-md);\n  }\n  .kpi-top {\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n    margin-bottom: 12px;\n  }\n  .kpi-meta {\n    display: flex;\n    flex-direction: column;\n  }\n  .kpi-title {\n    font-size: 12.5px;\n    font-weight: 600;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.04em;\n  }\n  .kpi-icon-wrap {\n    width: 36px;\n    height: 36px;\n    border-radius: var(--radius-md);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--bg-subtle);\n    color: var(--accent);\n  }\n  .kpi-value-row {\n    display: flex;\n    align-items: baseline;\n    gap: 8px;\n    margin-bottom: 8px;\n  }\n  .kpi-value {\n    font-size: 28px;\n    font-weight: 700;\n    font-family: var(--font-mono);\n    color: var(--text-main);\n    letter-spacing: -0.02em;\n    line-height: 1.1;\n  }\n  .kpi-value.unavailable-text {\n    font-size: 22px;\n    color: var(--text-subtle);\n    font-weight: 600;\n  }\n  .kpi-badge-unavailable {\n    display: inline-block;\n    font-size: 10px;\n    font-weight: 600;\n    padding: 2px 6px;\n    border-radius: 4px;\n    background: var(--bg-muted);\n    color: var(--text-muted);\n  }\n\n  .kpi-bottom {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    font-size: 12px;\n    color: var(--text-muted);\n    padding-top: 10px;\n    border-top: 1px solid var(--border-subtle);\n  }\n  .delta-pill {\n    display: inline-flex;\n    align-items: center;\n    gap: 3px;\n    font-size: 11.5px;\n    font-weight: 600;\n    font-family: var(--font-mono);\n  }\n  .delta-pill.good { color: var(--success-text); }\n  .delta-pill.bad { color: var(--danger-text); }\n  .delta-pill.neutral { color: var(--text-muted); }\n\n  /* Circular progress indicator */\n  .ring-wrap {\n    position: relative;\n    width: 44px;\n    height: 44px;\n    flex-shrink: 0;\n  }\n  .ring-svg {\n    transform: rotate(-90deg);\n    width: 44px;\n    height: 44px;\n  }\n  .ring-bg {\n    stroke: var(--bg-muted);\n    stroke-width: 4;\n    fill: none;\n  }\n  .ring-progress {\n    stroke: var(--accent);\n    stroke-width: 4;\n    fill: none;\n    stroke-linecap: round;\n    transition: stroke-dashoffset 0.8s ease;\n  }\n  .ring-progress.good { stroke: var(--success); }\n  .ring-progress.warn { stroke: var(--warning); }\n  .ring-progress.danger { stroke: var(--danger); }\n\n  /* ── AI Insights Banner ──────────────────────────── */\n  .ai-summary-card {\n    background: linear-gradient(135deg, rgba(37, 99, 235, 0.04), rgba(79, 70, 229, 0.06));\n    border: 1px solid rgba(37, 99, 235, 0.2);\n    border-radius: var(--radius-lg);\n    padding: 20px;\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n  }\n  .ai-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n  }\n  .ai-title {\n    font-size: 14px;\n    font-weight: 700;\n    color: var(--accent-text);\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n  .ai-model-tag {\n    font-size: 11px;\n    font-family: var(--font-mono);\n    color: var(--text-muted);\n    background: var(--bg-surface);\n    padding: 2px 8px;\n    border-radius: var(--radius-full);\n    border: 1px solid var(--border);\n  }\n  .ai-overview-text {\n    font-size: 13.5px;\n    color: var(--text-main);\n    line-height: 1.6;\n  }\n  .ai-takeaways-list {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 10px;\n    margin-top: 4px;\n  }\n  .ai-takeaway-item {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 10px 14px;\n    font-size: 12.5px;\n    color: var(--text-main);\n    display: flex;\n    align-items: flex-start;\n    gap: 8px;\n    box-shadow: var(--shadow-sm);\n  }\n\n  /* ── Charts Grid ─────────────────────────────────── */\n  .charts-grid {\n    display: grid;\n    grid-template-columns: repeat(12, 1fr);\n    gap: 16px;\n  }\n  .col-12 { grid-column: span 12; }\n  .col-8  { grid-column: span 8; }\n  .col-6  { grid-column: span 6; }\n  .col-4  { grid-column: span 4; }\n  @media (max-width: 960px) {\n    .col-8, .col-6, .col-4 { grid-column: span 12; }\n  }\n\n  .chart-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-lg);\n    padding: 18px 20px;\n    box-shadow: var(--shadow-card);\n    display: flex;\n    flex-direction: column;\n    min-height: 280px;\n  }\n  .chart-card-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 14px;\n  }\n  .chart-title {\n    font-size: 14px;\n    font-weight: 600;\n    color: var(--text-main);\n  }\n  .chart-subtitle {\n    font-size: 11.5px;\n    color: var(--text-muted);\n  }\n  .chart-container {\n    position: relative;\n    flex: 1;\n    min-height: 220px;\n    width: 100%;\n  }\n\n  /* ── Issues Table & Lists ────────────────────────── */\n  .table-container {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-lg);\n    box-shadow: var(--shadow-card);\n    overflow: hidden;\n  }\n  .table-toolbar {\n    padding: 14px 18px;\n    border-bottom: 1px solid var(--border);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    flex-wrap: wrap;\n    gap: 12px;\n  }\n  .filters-group {\n    display: flex;\n    gap: 8px;\n    align-items: center;\n    flex-wrap: wrap;\n  }\n  .filter-select {\n    font-size: 12px;\n    font-weight: 500;\n    color: var(--text-main);\n    background: var(--bg-subtle);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 5px 10px;\n    cursor: pointer;\n    outline: none;\n  }\n\n  table.data-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n    text-align: left;\n  }\n  table.data-table th {\n    background: var(--bg-subtle);\n    color: var(--text-muted);\n    font-weight: 600;\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 0.04em;\n    padding: 10px 16px;\n    border-bottom: 1px solid var(--border);\n    user-select: none;\n    white-space: nowrap;\n  }\n  table.data-table td {\n    padding: 12px 16px;\n    border-bottom: 1px solid var(--border-subtle);\n    vertical-align: middle;\n    color: var(--text-main);\n  }\n  table.data-table tr:hover td {\n    background: var(--bg-subtle);\n  }\n  table.data-table tr:last-child td {\n    border-bottom: none;\n  }\n  td.mono-num {\n    font-family: var(--font-mono);\n    font-variant-numeric: tabular-nums;\n  }\n\n  /* Badges and Chips */\n  .badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    font-size: 11px;\n    font-weight: 600;\n    padding: 2px 7px;\n    border-radius: 4px;\n    white-space: nowrap;\n  }\n  .badge-p0 { background: var(--p0-bg); color: var(--p0); }\n  .badge-p1 { background: var(--p1-bg); color: var(--p1); }\n  .badge-p2 { background: var(--p2-bg); color: var(--p2); }\n  .badge-p3 { background: var(--p3-bg); color: var(--p3); }\n\n  .badge-fatal { background: var(--danger-light); color: var(--danger-text); }\n  .badge-anr { background: var(--warning-light); color: var(--warning-text); }\n  .badge-nonfatal { background: var(--bg-subtle); color: var(--text-muted); border: 1px solid var(--border); }\n\n  .badge-lifecycle-new { background: #fee2e2; color: #991b1b; }\n  .badge-lifecycle-persistent { background: #fef3c7; color: #92400e; }\n  .badge-lifecycle-regressed { background: #ede9fe; color: #5b21b6; }\n  .badge-lifecycle-resolved { background: #dcfce7; color: #166534; }\n  .badge-lifecycle-not-observed { background: var(--bg-muted); color: var(--text-muted); }\n\n  /* priority.trend badge（#74）。與 lifecycle badge 分色，兩者是不同的模型。 */\n  .badge-trend-new { background: var(--danger-light); color: var(--danger-text); }\n  .badge-trend-worsening { background: var(--warning-light); color: var(--warning-text); }\n  .badge-trend-improving { background: var(--success-light); color: var(--success-text); }\n  .badge-trend-stable { background: var(--bg-subtle); color: var(--text-muted); border: 1px solid var(--border); }\n\n  .badge-status {\n    padding: 2px 8px;\n    border-radius: var(--radius-full);\n    font-size: 10.5px;\n    font-weight: 600;\n  }\n  .badge-latest { background: var(--accent-light); color: var(--accent-text); }\n  .badge-active { background: var(--success-light); color: var(--success-text); }\n  .badge-maintenance { background: var(--warning-light); color: var(--warning-text); }\n  .badge-deprecated { background: var(--bg-muted); color: var(--text-muted); }\n  .badge-legacy { background: var(--bg-muted); color: var(--text-muted); border: 1px dashed var(--border-hover); }\n  .badge-info { background: var(--accent-light); color: var(--accent-text); }\n\n  .badge-stability-improving { background: var(--success-light); color: var(--success-text); }\n  .badge-stability-degrading { background: var(--danger-light); color: var(--danger-text); }\n  .badge-stability-stable { background: var(--accent-light); color: var(--accent-text); }\n  .badge-stability-baseline { background: var(--bg-muted); color: var(--text-muted); }\n\n  /* ── Version / Release Detail Modal ── */\n  .modal-overlay {\n    position: fixed;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: rgba(0, 0, 0, 0.6);\n    backdrop-filter: blur(4px);\n    z-index: 100;\n    display: none;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n  }\n  .modal-overlay.active { display: flex; }\n  .modal-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-lg);\n    width: 100%;\n    max-width: 900px;\n    max-height: 90vh;\n    overflow-y: auto;\n    box-shadow: var(--shadow-lg);\n    display: flex;\n    flex-direction: column;\n  }\n  .modal-header {\n    padding: 16px 20px;\n    border-bottom: 1px solid var(--border);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    position: sticky;\n    top: 0;\n    background: var(--bg-surface);\n    z-index: 10;\n  }\n  .modal-title-group {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n  }\n  .modal-close-btn {\n    background: transparent;\n    border: none;\n    cursor: pointer;\n    color: var(--text-muted);\n    font-size: 24px;\n    line-height: 1;\n    padding: 2px 8px;\n    border-radius: var(--radius-sm);\n  }\n  .modal-close-btn:hover {\n    background: var(--bg-subtle);\n    color: var(--text-main);\n  }\n  .modal-body {\n    padding: 20px;\n    display: flex;\n    flex-direction: column;\n    gap: 18px;\n  }\n  .release-stat-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n    gap: 12px;\n  }\n  .release-stat-box {\n    background: var(--bg-subtle);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 12px 14px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n  .release-stat-label {\n    font-size: 11px;\n    color: var(--text-muted);\n    font-weight: 500;\n  }\n  .release-stat-value {\n    font-size: 18px;\n    font-weight: 700;\n    color: var(--text-main);\n    font-family: var(--font-mono);\n  }\n  .sub-pill-btn {\n    padding: 4px 12px;\n    font-size: 12px;\n    font-weight: 600;\n    border-radius: var(--radius-full);\n    border: 1px solid var(--border);\n    background: var(--bg-subtle);\n    color: var(--text-muted);\n    cursor: pointer;\n    transition: all 0.15s;\n  }\n  .sub-pill-btn.active {\n    background: var(--accent);\n    color: #ffffff;\n    border-color: var(--accent);\n  }\n\n  /* ── Data Sources Health Card ── */\n  .data-sources-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-lg);\n    padding: 16px 20px;\n    margin-bottom: 20px;\n    box-shadow: var(--shadow-sm);\n  }\n  .data-sources-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 14px;\n    flex-wrap: wrap;\n    gap: 8px;\n  }\n  .data-sources-title {\n    font-size: 14px;\n    font-weight: 700;\n    color: var(--text-main);\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .data-sources-run-info {\n    font-size: 12px;\n    color: var(--text-muted);\n  }\n  .data-sources-grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 12px;\n  }\n  @media (max-width: 992px) {\n    .data-sources-grid { grid-template-columns: repeat(2, 1fr); }\n  }\n  @media (max-width: 576px) {\n    .data-sources-grid { grid-template-columns: 1fr; }\n  }\n  .data-source-item {\n    background: var(--bg-subtle);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 12px 14px;\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    transition: border-color 0.15s;\n  }\n  .data-source-item:hover {\n    border-color: var(--border-hover);\n  }\n  .data-source-item-top {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n  }\n  .data-source-name {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--text-main);\n  }\n  .data-source-freshness {\n    font-size: 12px;\n    color: var(--text-muted);\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n  }\n  .data-source-note {\n    font-size: 11.5px;\n    color: var(--text-subtle);\n    word-break: break-word;\n    margin-top: 2px;\n    line-height: 1.4;\n  }\n  .data-source-note.warning {\n    color: var(--warning-text);\n  }\n  .data-source-note.error {\n    color: var(--danger-text);\n  }\n\n  /* Issue Accordion Item */\n  .issue-accordion {\n    border-bottom: 1px solid var(--border);\n  }\n  .issue-accordion:last-child {\n    border-bottom: none;\n  }\n  .issue-summary-row {\n    padding: 14px 18px;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    transition: background 0.15s;\n    user-select: none;\n  }\n  .issue-summary-row:hover {\n    background: var(--bg-subtle);\n  }\n  .issue-rank {\n    font-family: var(--font-mono);\n    font-size: 14px;\n    font-weight: 700;\n    color: var(--text-subtle);\n    min-width: 24px;\n  }\n  .issue-title-group {\n    flex: 1;\n    min-width: 0;\n  }\n  .issue-main-title {\n    font-size: 13.5px;\n    font-weight: 600;\n    color: var(--text-main);\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n  .issue-sub-title {\n    font-size: 11.5px;\n    font-family: var(--font-mono);\n    color: var(--text-muted);\n    margin-top: 2px;\n  }\n  .issue-stats-group {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    font-size: 12.5px;\n    font-family: var(--font-mono);\n    color: var(--text-muted);\n    white-space: nowrap;\n  }\n\n  .issue-detail-panel {\n    display: none;\n    padding: 16px 20px 20px;\n    background: var(--bg-subtle);\n    border-top: 1px dashed var(--border);\n    flex-direction: column;\n    gap: 14px;\n  }\n  .issue-detail-panel.open {\n    display: flex;\n  }\n  .detail-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n    gap: 14px;\n  }\n  .detail-box {\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-md);\n    padding: 12px 14px;\n  }\n  .detail-box-title {\n    font-size: 11px;\n    font-weight: 700;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.04em;\n    margin-bottom: 6px;\n  }\n  .detail-box-content {\n    font-size: 12.5px;\n    color: var(--text-main);\n    line-height: 1.5;\n  }\n  pre.code-stack {\n    font-family: var(--font-mono);\n    font-size: 11px;\n    background: var(--bg-surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius-sm);\n    padding: 10px;\n    max-height: 200px;\n    overflow-x: auto;\n    white-space: pre-wrap;\n    word-break: break-all;\n    color: var(--text-main);\n  }\n\n  .btn-copy-prompt {\n    font-size: 11.5px;\n    font-weight: 600;\n    padding: 6px 12px;\n    border-radius: var(--radius-md);\n    background: var(--accent);\n    color: #ffffff;\n    border: none;\n    cursor: pointer;\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    transition: background 0.15s;\n    align-self: flex-start;\n  }\n  .btn-copy-prompt:hover {\n    background: var(--accent-hover);\n  }\n\n  /* Empty state */\n  .empty-state {\n    padding: 48px 24px;\n    text-align: center;\n    color: var(--text-muted);\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 8px;\n  }\n  .empty-state-title {\n    font-size: 15px;\n    font-weight: 600;\n    color: var(--text-main);\n  }\n\n  /* Responsive styles */\n  @media (max-width: 768px) {\n    .sidebar {\n      transform: translateX(-100%);\n    }\n    .sidebar.mobile-open {\n      transform: translateX(0);\n    }\n    .layout-wrapper {\n      margin-left: 0 !important;\n    }\n    .mobile-toggle {\n      display: inline-flex;\n    }\n    .search-input {\n      width: 140px;\n    }\n    .search-input:focus {\n      width: 180px;\n    }\n  }\n\n  /* Toast Notification */\n  .toast {\n    position: fixed;\n    bottom: 24px;\n    right: 24px;\n    background: var(--text-main);\n    color: var(--bg-surface);\n    padding: 10px 18px;\n    border-radius: var(--radius-md);\n    font-size: 13px;\n    font-weight: 500;\n    box-shadow: var(--shadow-lg);\n    z-index: 999;\n    opacity: 0;\n    transform: translateY(8px);\n    transition: all 0.2s ease;\n    pointer-events: none;\n  }\n  .toast.show {\n    opacity: 1;\n    transform: translateY(0);\n  }\n</style>\n'


def get_shell_top_html() -> str:
    """Returns Doctype, head, title, and viewport tags."""
    return '<!DOCTYPE html>\n<html lang="zh-Hant" data-theme="light">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Crashlytics Engineering Dashboard V2</title>\n'


def get_sidebar_html() -> str:
    """Returns the 8-item navigation sidebar HTML markup."""
    return '<aside class="sidebar" id="sidebar">\n  <div class="sidebar-header">\n    <div class="brand-logo">\n      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">\n        <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>\n      </svg>\n    </div>\n    <div class="brand-info">\n      <div class="brand-title">Crashlytics <span class="brand-badge">V2</span></div>\n      <div class="brand-sub">Telemetry Dashboard</div>\n    </div>\n  </div>\n\n' + get_nav_menu_html() + '\n  <div class="sidebar-footer">\n    <button class="collapse-btn" onclick="toggleSidebar()" title="折疊導覽列">\n      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg>\n    </button>\n  </div>\n</aside>\n'


def get_header_html() -> str:
    """Returns the top header markup (app selector, search, period filter, theme toggle)."""
    return '<div class="layout-wrapper">\n\n  <!-- ── Top Header ──────────────────────────────── -->\n  <header class="top-header">\n    <div class="header-left">\n      <button class="mobile-toggle" onclick="toggleMobileMenu()">\n        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg>\n      </button>\n\n      <div class="app-select-wrap">\n        <span class="app-label">App:</span>\n        <select id="appSelector" class="app-selector" onchange="switchApp(this.value)">\n          <!-- Populated dynamically -->\n        </select>\n      </div>\n\n      <div class="period-filters">\n        <button class="period-btn" onclick="setPeriod(7)" id="p-7d">7d</button>\n        <button class="period-btn active" onclick="setPeriod(30)" id="p-30d">30d</button>\n        <button class="period-btn" onclick="setPeriod(90)" id="p-90d">90d</button>\n      </div>\n    </div>\n\n    <div class="header-right">\n      <div class="search-box">\n        <svg class="search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>\n        <input type="text" class="search-input" id="globalSearch" placeholder="搜尋問題、檔案、ID..." oninput="handleSearch(this.value)">\n      </div>\n\n      <div class="source-badges" id="headerSourceBadges">\n        <!-- Populated dynamically -->\n      </div>\n\n      <button class="theme-toggle-btn" onclick="toggleTheme()" title="切換深/淺色主題">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/></svg>\n      </button>\n    </div>\n  </header>\n'


def get_shell_bottom_html() -> str:
    """Returns the main/layout wrapper closing tags and toast notification element."""
    return '  </main>\n</div>\n\n<div class="toast" id="toast">已複製到剪貼簿</div>\n'


def get_shell_js_top() -> str:
    """Returns top-level client state initialization, navigation, and theme handlers."""
    return 'const DATA = __DATA__;\nlet curAppId = DATA.default_app || Object.keys(DATA.apps || {})[0];\nlet curPeriodDays = 30;\nlet searchQuery = "";\nlet chartInstances = {};\n\nconst $ = id => document.getElementById(id);\n\n// Theme support\ntry {\n  const savedTheme = localStorage.getItem("ct_theme") || "light";\n  document.documentElement.dataset.theme = savedTheme;\n} catch (e) {}\n\nfunction toggleTheme() {\n  const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";\n  document.documentElement.dataset.theme = next;\n  try { localStorage.setItem("ct_theme", next); } catch (e) {}\n  renderCharts();\n}\n\nfunction toggleSidebar() {\n  $("sidebar").classList.toggle("collapsed");\n}\n\nfunction toggleMobileMenu() {\n  $("sidebar").classList.toggle("mobile-open");\n}\n\nfunction showToast(msg) {\n  const t = $("toast");\n  t.textContent = msg;\n  t.classList.add("show");\n  setTimeout(() => t.classList.remove("show"), 2000);\n}\n\n' + get_navigation_js() + 'function isUsablePeriodSnapshot(snap) {\n  if (!snap) return false;\n  if (snap.status === "error" || snap.status === "insufficient_data") return false;\n  const usStatus = snap.kpi?.affected_users?.status;\n  if (usStatus === "error" || usStatus === "insufficient_data") return false;\n  return true;\n}\n\nfunction switchApp(appId) {\n  if (DATA.apps && DATA.apps[appId]) {\n    curAppId = appId;\n    $("appSelector").value = appId;\n    const app = DATA.apps[appId];\n    if (app.periods) {\n      const curSnap = app.periods[String(curPeriodDays)];\n      if (!isUsablePeriodSnapshot(curSnap)) {\n        const avail = Object.keys(app.periods)\n          .map(Number)\n          .filter(d => isUsablePeriodSnapshot(app.periods[String(d)]))\n          .sort((a,b) => a - b);\n        curPeriodDays = avail.includes(30) ? 30 : (avail[0] || (Object.keys(app.periods).map(Number).sort((a,b) => a - b)[0] || 30));\n      }\n    }\n    renderAll();\n    ' + get_route_revalidate_call().rstrip("\n") + '\n  }\n}\n\nlet curSortField = "priority";\nlet curSortAsc = false;\n\nfunction setPeriod(days) {\n  const app = getCurAppData();\n  if (!app) return;\n  const availableDays = (app?.daily_trend || []).length || app?.period?.days || 30;\n  const snap = app.periods ? app.periods[String(days)] : null;\n  const hasPeriod = (snap != null) || (!app.periods && days <= availableDays);\n  if (!hasPeriod) {\n    showToast(`目前資料無 ${days} 天之獨立數據`);\n    return;\n  }\n  if (snap && !isUsablePeriodSnapshot(snap)) {\n    showToast(`${days} 天數據查詢異常：${snap.error_message || "權威彙總缺失"}`);\n    return;\n  }\n  curPeriodDays = Number(days);\n  renderAll();\n}\n\nfunction setSort(field) {\n  if (curSortField === field) {\n    curSortAsc = !curSortAsc;\n  } else {\n    curSortField = field;\n    curSortAsc = false;\n  }\n  renderIssuesList();\n}\n\nfunction handleSearch(val) {\n  searchQuery = (val || "").trim().toLowerCase();\n  renderIssuesList();\n}\n\nfunction getCurAppData() {\n  return (DATA.apps && DATA.apps[curAppId]) ? DATA.apps[curAppId] : null;\n}\n\nfunction getCurPeriodSnapshot() {\n  const app = getCurAppData();\n  if (!app) return null;\n  if (app.periods) {\n    const snap = app.periods[String(curPeriodDays)];\n    if (snap && isUsablePeriodSnapshot(snap)) {\n      return snap;\n    }\n    const avail = Object.keys(app.periods)\n      .map(Number)\n      .filter(d => isUsablePeriodSnapshot(app.periods[String(d)]))\n      .sort((a,b) => a - b);\n    if (avail.length > 0) {\n      const fallbackDays = avail.includes(30) ? 30 : avail[0];\n      return app.periods[String(fallbackDays)];\n    }\n    if (snap) return snap;\n  }\n  return {\n    period: app.period || { days: curPeriodDays },\n    kpi: app.kpi || {},\n    daily_trend: app.daily_trend || [],\n    version_health: app.version_health || [],\n    distributions: app.distributions || {},\n    top_issues: app.top_issues || [],\n    ai_summary: app.ai_summary || {},\n  };\n}\n\n'


def get_shell_js_bottom() -> str:
    """Returns the full render dispatcher renderAll() and page initialization listeners.

    deep-link routing 於首次 render 之後才初始化 (#78)：套用 route 需要 DATA 與
    已渲染的 DOM（例如開啟 release 詳情）；``initDeepLinkRouting`` 本身具備冪等性。
    """
    return '// Full Render\nfunction renderAll() {\n  renderHeader();\n  renderDataSourcesHealth();\n  renderReleaseDecisions();\n  renderReleaseComparison();\n  renderKPIs();\n  renderAISummaries();\n  renderCharts();\n  renderOverviewTopIssuesPreview();\n  updateVersionFilterOptions(true);\n  renderIssuesList();\n  renderVersionHealth();\n  renderDevicesTable();\n  renderReleasesTable();\n  renderPipelines();\n  renderSettings();\n}\n\n// Initialize on page load\ndocument.addEventListener("DOMContentLoaded", () => {\n  renderAll();\n  ' + get_routing_init_call().rstrip("\n") + '\n});\nif (document.readyState === "complete" || document.readyState === "interactive") {\n  renderAll();\n  ' + get_routing_init_call().rstrip("\n") + '\n}\n'
